const FloatingHashtag: React.FC<{
  tag: string; x: number; y: number; size: number; color: string; delay: number;
}> = ({ tag, x, y, size, color, delay }) => {
  const frame = useCurrentFrame();
  const { fps: f } = useVideoConfig();
  const progress = spring({ frame, fps: f, delay, config: { damping: 200 } });
  const drift = Math.sin((frame + delay * 10) * 0.03) * 18;
  return (
    <div
      style={{
        position: "absolute",
        left: x,
        top: y + drift,
        opacity: interpolate(progress, [0, 1], [0, 0.7]),
        transform: `scale(${interpolate(progress, [0, 1], [0.5, 1])}) translateY(${interpolate(progress, [0, 1], [40, 0])}px)`,
        fontSize: size,
        fontWeight: 700,
        color,
        fontFamily: "'Inter', sans-serif",
        letterSpacing: "-0.02em",
        whiteSpace: "nowrap",
        textShadow: `0 0 40px ${color}55`,
        pointerEvents: "none",
      }}
    >
      {tag}
    </div>
  );
};

