// ─── Scene 2: The Fraction ────────────────────────────────────────────────────
const Scene2Fraction: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: f } = useVideoConfig();

  const total = 200;
  const active = 12;

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <AbsoluteFill style={{ display: "flex", alignItems: "center", justifyContent: "center" }}>
        <div style={{ display: "flex", flexWrap: "wrap", gap: 16, width: 2400, justifyContent: "center" }}>
          {Array.from({ length: total }).map((_, i) => {
            const isActive = i < active;
            const delay = i * 2;
            const progress = spring({ frame, fps: f, delay, config: { damping: 200 } });
            const pulseScale = isActive ? 1 + Math.sin((frame - delay) * 0.12) * 0.08 : 1;
            return (
              <div
                key={i}
                style={{
                  width: 90,
                  height: 90,
                  borderRadius: 18,
                  backgroundColor: isActive ? COLORS.pink : "rgba(255,255,255,0.06)",
                  border: isActive ? `2px solid ${COLORS.pink}` : "2px solid rgba(255,255,255,0.08)",
                  opacity: interpolate(progress, [0, 1], [0, isActive ? 1 : 0.35]),
                  transform: `scale(${interpolate(progress, [0, 1], [0.2, 1]) * (isActive ? pulseScale : 1)})`,
                  boxShadow: isActive ? `0 0 24px ${COLORS.pink}66` : "none",
                }}
              />
            );
          })}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

