          const r = t < 0 ? 0 : maxR * t;
          const opacity = t < 0 ? 0 : interpolate(t, [0, 0.3, 1], [0, 0.6, 0]);
          return (
            <circle key={i} cx={1920} cy={1080} r={r} fill="none" stroke={COLORS.pink} strokeWidth={4} opacity={opacity} />
