// Each column holds 3 cards stacked with generous vertical spacing
const CardColumn: React.FC<{
  discovered: boolean;
  cards: Array<{
    avatarColor: string;
    imageColors: [string, string];
    lines: number[];
    likeCount: string;
    commentCount: string;
    hashtag: string;
    delay: number;
    startOffset: number;
  }>;
}> = ({ discovered, cards }) => {
  const frame = useCurrentFrame();
  const { fps: f } = useVideoConfig();

  return (
    <>
      {cards.map((card, i) => {
        const progress = spring({ frame, fps: f, delay: card.delay, config: { damping: 200 } });
        const continuousTravel = discovered
          ? interpolate(frame, [card.delay, card.delay + 180], [0, -280], { extrapolateLeft: "clamp", extrapolateRight: "clamp" })
          : interpolate(frame, [card.delay, card.delay + 180], [0, 280], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
        const enterY = interpolate(progress, [0, 1], [discovered ? 100 : -100, 0]);

        return (
          <div
            key={i}
            style={{
              position: "absolute",
              top: "50%",
              transform: `translateY(calc(-50% + ${card.startOffset + continuousTravel + enterY}px))`,
              opacity: interpolate(progress, [0, 1], [0, 1]),
            }}
          >
            <PostCard
              discovered={discovered}
              avatarColor={card.avatarColor}
              imageColors={card.imageColors}
              lines={card.lines}
              likeCount={card.likeCount}
              commentCount={card.commentCount}
              hashtag={card.hashtag}
            />
          </div>
        );
      })}
    </>
  );
};

